%[text] # Es 3
f = @ (t) 2.*exp(-2.*t) - t;
a = 0;
b = 1;

x = linspace(a, b, 10);
p_y = f(x);

r = polyfit(x, p_y, 1) %[output:8286ab0b]

plot(x, p_y, "*", x, polyval(r, x)); %[output:9ad1b034]
M = [x' ones(length(x), 1)];
A = M' * M;
b = M' * p_y';
z = A \ b %[output:8877a183]

%%
%[text] ## Es 4
f = @ (x) 5.*cos(pi.*x.^2) - exp(x);
a = 0;
b = 1;

x = linspace(a, b, 5);
p_y = f(x);

r = polyfit(x, p_y, 1);

plot(x, p_y, '*', x, polyval(r, x), mean(x), polyval(r, mean(x)), "O"); %[output:470081d1]

p = polyfit(x, p_y, length(x)-1);
p_x = linspace(a, b, 100);
p_y = polyval(p, p_x);

p_roots = roots(p) %[output:65c077b2]
p_roots = p_roots(imag(p_roots) == 0 & p_roots >= a & p_roots <= b) %[output:5f999618]

plot(x, p_y, '*', p_x, p_y, p_roots, polyval(p, p_roots), "O") %[output:1f957e52]

