%[text] ## Es 7
x = [1 2 3 4 5];
p_y = [4.9 8 12.3 23.1 36.5];

a = min(x);
b = max(x);

r = polyfit(x, log(p_y), 1);
A = r(1);
C = exp(r(2));

f = @(x) C.*exp(A.*x);

f_x = linspace(a, b, 100);
f_y = f(f_x);

plot(x, p_y, "*", f_x, f_y, 2.5, f(2.5), "O"); %[output:654430cb]

%%
%[text] ## Es di riepilogo
%%
%[text] ## Es 2
T = [0 10 20 30 40 50 60 70];
C = [96.4 46.3 21.2 17.89 10.1 6.9 3.5 1.9];
z = 0:0.2:70;

plot(T, C, "*"); %[output:76c1d6d7]
hold on; %[output:76c1d6d7]

% Parte 1

% retta  di regressione
r = polyfit(T, C, 1);
plot(z, polyval(r, z)); %[output:76c1d6d7]

% spline lineare
s1 = griddedInterpolant(T,C,'linear');
plot(z, s1(z)); %[output:76c1d6d7]

% polinomio interpolatore
p = polyfit(T, C, length(T)-1);
plot(z, polyval(p, z), "--"); %[output:76c1d6d7]


% Parte 2

t = 62;
disp("r(62)= " + polyval(r, t)); %[output:688ea40f]

disp("s1(62)= " + s1(t)); %[output:6723c6e1]

disp("p(62)= " + polyval(p, t)); %[output:72fe10a1]

% Parte 3

sum((C - polyval(r, T)).^2) %[output:3ea3a277]

hold off; %[output:76c1d6d7]


