%[text] ## Es 6
p_x = [1 2 3 4 5];
p_y = [0.25 0.31 0.35 0.4 0.41];

a = min(p_x);
b = max(p_x);

Y = p_x./p_y;
r = polyfit(p_x, Y, 1);
B = r(1) %[output:352ce12a]
A = r(2) %[output:82d6be62]

plot(p_x, p_y, "*"); %[output:5faedb8f]
hold on; %[output:5faedb8f]

f = @(x) x./(A + B.*x);
f_x = linspace(a, b, 100);
f_y = f(f_x);

plot(f_x, f_y); %[output:5faedb8f]

f(4.5) %[output:18a7dc09]

hold off; %[output:5faedb8f]

%%
%[text] ## Es 6 gemini
% 1. Inserimento dei dati
x = [1 2 3 4 5];
y = [0.25 0.31 0.35 0.4 0.41];

% 2. Linearizzazione dei dati
% Costruiamo il nuovo vettore delle ordinate Y = x / y
Y = x ./ y; 

% 3. Calcolo della retta di regressione
r = polyfit(x, Y, 1);

% 4. Estrazione dei coefficienti
% Ricorda: polyfit restituisce prima la pendenza (B) e poi l'intercetta (A)
B = r(1) %[output:69d79f44]
A = r(2) %[output:7b30b408]

% 5. Definizione della funzione approssimante originale
f = @(x) x ./ (A + B .* x);

% 6. Valutazione della funzione in x = 4.5
x_val = 4.5;
y_val = f(x_val);
fprintf('Il valore della funzione approssimante in x = %.2f è: %.4f\n', x_val, y_val); %[output:9a046c2b]

% 7. Creazione del grafico
% Vettore fitto per disegnare la curva in modo continuo
f_x = linspace(min(x), max(x), 100); 
f_y = f(f_x);

figure; %[output:35530930]
plot(x, y, '*r', 'MarkerSize', 8); % Punti dei dati originali %[output:35530930]
hold on; %[output:35530930]
plot(f_x, f_y, 'b-', 'LineWidth', 1.5); % Curva della funzione approssimante %[output:35530930]
hold off; %[output:35530930]

% Dettagli e formattazione del grafico
legend('Dati (x,y)', 'Funzione y = x/(A+Bx)', 'Location', 'southeast'); %[output:35530930]
xlabel('x'); %[output:35530930]
ylabel('y'); %[output:35530930]
title('Approssimazione ai Minimi Quadrati'); %[output:35530930]
grid on; %[output:35530930]

